CREATE TABLE suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,tax_code VARCHAR(14) NOT NULL,contact_name VARCHAR(150) NOT NULL,contact_phone VARCHAR(20) NOT NULL,payment_terms VARCHAR(250) NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',version BIGINT NOT NULL DEFAULT 1,FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CHECK(status IN ('ACTIVE','DISCONTINUED')));
CREATE TABLE supplier_receipt_references(supplier_id BIGINT UNSIGNED NOT NULL,receipt_reference VARCHAR(100) NOT NULL,PRIMARY KEY(supplier_id,receipt_reference),FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
